import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import {hashManifestValue} from '../../tools/staging/create-source-manifest'
const db=createPostgresConnection('postgres://m63_test_admin@127.0.0.1:55463/m68_qa',{tls:false})
try {
 const schema=(await db.query('select * from neuvetra.schema_migrations order by name')).rows
 if(schema.length!==13)throw Error('Untouched schema13 required')
 const tables=(await db.query<{tablename:string}>("select tablename from pg_tables where schemaname='neuvetra' order by tablename")).rows
 const rowHashes=[]
 for(const {tablename} of tables){if(!/^[a-z_]+$/.test(tablename))throw Error('Unsafe identifier');rowHashes.push({table:tablename,hashes:(await db.query<{value:any}>(`select to_jsonb(t) value from neuvetra.${tablename} t`)).rows.map(r=>hashManifestValue(r.value)).sort()})}
 const receipt={observedAt:new Date().toISOString(),database:'m68_qa',schemaVersion:13,rowHashes}
 const path=new URL('./m68-independent-baseline.json',import.meta.url)
 if(await Bun.file(path).exists())throw Error('Never overwrite baseline')
 await Bun.write(path,JSON.stringify(receipt,null,2)+'\n')
 console.log(JSON.stringify({tables:rowHashes.length,records:rowHashes.reduce((n,t)=>n+t.hashes.length,0),schemaVersion:13}))
}finally{await db.close()}

import {afterEach,expect,test} from 'bun:test'
import {annualEvidenceRequest,decodeAnnualElectricityEvidence} from '../../apps/site-web/src/lib/m68-api'
import {decodeAnnualEvidenceReport,readAnnualEvidenceReportHtml,listAnnualEvidenceReports,createAnnualEvidenceReport} from '../../apps/site-web/src/lib/m68-report-api'
const fixture=await Bun.file(new URL('./m68-independent-native-fixture.json',import.meta.url)).json()
const {company,annual,evidence,report,reportHtml}=fixture
const original=globalThis.fetch
const actor={accessToken:'synthetic-qa-token',userId:evidence.versions[0].createdBy,role:'owner' as const}
afterEach(()=>{globalThis.fetch=original})
async function refuses(fn:()=>Promise<unknown>){let denied=false;try{await fn()}catch{denied=true}expect(denied).toBe(true)}
test('actual native success history decodes including the full independent lifecycle',()=>{expect(decodeAnnualElectricityEvidence(evidence,company,annual).versions.length).toBeGreaterThan(10);expect(decodeAnnualEvidenceReport(report,evidence,annual).source.review).toBeNull()})
test('independent malformed values, false coverage, inherited review and duplicate-byte changes refuse',()=>{
 const index=evidence.versions.findIndex((v:any)=>v.links.length===2)
 for(const mutate of [(w:any)=>w.companyId=crypto.randomUUID(),(w:any)=>w.complete=true,(w:any)=>w.assurance='verified',(w:any)=>w.limitations.pop(),(w:any)=>w.versions[index].coverage.linkedDocumentMonths=2,(w:any)=>w.versions[index].coverage.unambiguousDocumentMonths=1,(w:any)=>w.versions[index].coverage.quantityDifferenceMonths=[],(w:any)=>w.versions[index].links[1]=structuredClone(w.versions[index].links[0]),(w:any)=>w.versions[index].links[1].source.sha256=w.versions[index].links[0].source.sha256,(w:any)=>w.versions[index].links[0].month='2023-02',(w:any)=>w.versions[index].links[0].quantityDifferenceReason=null,(w:any)=>delete w.versions[index].links[0].quantityDifferenceReason,(w:any)=>w.versions[index].links[0].confirmedBy=crypto.randomUUID(),(w:any)=>w.versions[index].annual.review=annual.versions[0].review,(w:any)=>w.versions[index].annual.months[0].quantityKwh='12345.000',(w:any)=>w.versions[index].annual.id=annual.versions.at(-1).id,(w:any)=>w.versions[index].previousVersionId=null]){const value=structuredClone(evidence);mutate(value);expect(()=>decodeAnnualElectricityEvidence(value,company,annual)).toThrow()}
 const reordered=JSON.parse(JSON.stringify(evidence,(_k,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).reverse()):v));expect(decodeAnnualElectricityEvidence(reordered,company,annual).versions.length).toBe(evidence.versions.length)
})
test('actual evidence transport refuses late header/body success and revoked actor callbacks',async()=>{
 for(const timing of ['headers','body']){const c=new AbortController();globalThis.fetch=(async()=>{if(timing==='headers'){c.abort();return Response.json(evidence)}return {ok:true,status:200,json:async()=>{c.abort();return evidence}} as Response}) as typeof fetch;await refuses(()=>annualEvidenceRequest({...actor,signal:c.signal},company,annual))}
 let unauthorized=0;globalThis.fetch=(async()=>new Response('',{status:403})) as typeof fetch;await refuses(()=>annualEvidenceRequest({...actor,onUnauthorized:()=>unauthorized++},company,annual));expect(unauthorized).toBe(1)
 let sent:any;globalThis.fetch=(async(_url,init)=>{sent=JSON.parse(String(init?.body));return Response.json(evidence)}) as typeof fetch;const a=annual.versions[0];const payload={annualVersionId:a.id,expectedAnnualInputSha256:a.inputSha256,expectedAnnualResultSha256:a.resultSha256,links:[],idempotencyKey:crypto.randomUUID()};await annualEvidenceRequest(actor,company,annual,'create',payload);expect(sent).toEqual(payload)
})
test('real report transport verifies metadata then exact bytes; rejects body abort, corruption and denied access',async()=>{
 let calls=0;globalThis.fetch=(async()=>++calls===1?Response.json(report):new Response(reportHtml,{headers:{'content-type':'text/html'}})) as typeof fetch;expect(await readAnnualEvidenceReportHtml(actor,evidence,annual,report)).toBe(reportHtml);expect(calls).toBe(2)
 for(const mode of ['denied','bytes','late']){calls=0;const c=new AbortController();globalThis.fetch=(async()=>{if(++calls===1)return Response.json(report);if(mode==='denied')return new Response('',{status:403});if(mode==='late'){c.abort();return new Response(reportHtml,{headers:{'content-type':'text/html'}})}return new Response(reportHtml+'forged',{headers:{'content-type':'text/html'}})}) as typeof fetch;await refuses(()=>readAnnualEvidenceReportHtml({...actor,signal:c.signal},evidence,annual,report))}
 globalThis.fetch=(async()=>Response.json({profile:report.profile,companyId:company,reports:[report,report]})) as typeof fetch;await refuses(()=>listAnnualEvidenceReports(actor,evidence,annual))
 for(const mode of ['list','create']){const c=new AbortController();globalThis.fetch=(async()=>({ok:true,status:200,json:async()=>{c.abort();return mode==='list'?{profile:report.profile,companyId:company,reports:[report]}:report}} as Response)) as typeof fetch;await refuses(()=>mode==='list'?listAnnualEvidenceReports({...actor,signal:c.signal},evidence,annual):createAnnualEvidenceReport({...actor,signal:c.signal},evidence,annual,{} as any))}
})
test('report frozen source, lineage, review and template substitutions refuse',()=>{for(const mutate of [(r:any)=>r.source.coverage.linkedDocumentMonths=12,(r:any)=>r.source.annual.months[0].quantityKwh='99.000',(r:any)=>r.sourceVersionId=evidence.versions.at(-1).id,(r:any)=>r.reviewState='accepted_bounded_internal_draft',(r:any)=>r.templateSha256='1'.repeat(64),(r:any)=>r.source.links[0].quantityDifferenceReason='Changed later']){const r=structuredClone(report);mutate(r);expect(()=>decodeAnnualEvidenceReport(r,evidence,annual)).toThrow()}})
test('Docker web/runtime stages and deny-by-default context include every new imported M68 module',async()=>{
 const docker=await Bun.file(new URL('../../Dockerfile.staging',import.meta.url)).text(),ignore=await Bun.file(new URL('../../Dockerfile.staging.dockerignore',import.meta.url)).text(),web=docker.split('FROM workspace AS web-build')[1]!.split('FROM workspace AS production-dependencies')[0]!,runtime=docker.split('FROM python:')[1]!
 for(const name of ['m68-contract.ts','m68-template.ts'])expect(web).toContain('packages/neuvetra-database/src/'+name)
 for(const file of ['packages/neuvetra-database/src/m68.ts','packages/neuvetra-database/src/m68-contract.ts','packages/neuvetra-database/src/m68-template.ts','packages/neuvetra-database/src/m68-report.ts','packages/neuvetra-database/src/migrations/0014_annual_electricity_evidence.sql','apps/site-api/src/workspace/m68-routes.ts','apps/site-api/src/workspace/m68-report-routes.ts']){expect(runtime).toContain(file);expect(ignore.split(/\r?\n/)).toContain('!'+file)}
})

import {beforeAll,afterAll,expect,test} from 'bun:test'
import {createPostgresConnection,HostedWorkspaceDatabase} from '../../packages/neuvetra-database/src/hosted'
import {migratePrivateStaging,readMigrationManifest,provisionStagingRoster} from '../../packages/neuvetra-database/src/staging-migrations'
import {createStagingServer} from '../../apps/site-api/src/staging/server'
import {decodeAnnualElectricityWorksheet} from '../../apps/site-web/src/lib/m67-api'
import {decodeAnnualElectricityEvidence} from '../../apps/site-web/src/lib/m68-api'
import {decodeAnnualEvidenceReport} from '../../apps/site-web/src/lib/m68-report-api'
import {readAnnualElectricityEvidence,annualEvidenceResultHash} from '../../packages/neuvetra-database/src/m68'
import {readAnnualEvidenceReports} from '../../packages/neuvetra-database/src/m68-report'
import {M68_LIMITATIONS} from '../../packages/neuvetra-database/src/m68-contract'
import {M67_LIMITATIONS} from '../../packages/neuvetra-database/src/m67-contract'
import {hashManifestValue} from '../../tools/staging/create-source-manifest'
import type {WorkspaceConnection,WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
const url=process.env.M68_QA_DATABASE_URL
if(url!=='postgres://m63_test_admin@127.0.0.1:55463/m68_qa')throw Error('Dedicated m68_qa only; explicit URL required')
const REF='abcdefghijklmnopqrst',ORIGIN='http://127.0.0.1:36668',company=crypto.randomUUID(),otherCompany=crypto.randomUUID()
const ids={owner:crypto.randomUUID(),admin:crypto.randomUUID(),member:crypto.randomUUID(),other:crypto.randomUUID(),outsider:crypto.randomUUID(),uninvited:crypto.randomUUID()}
const hash=(v:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(v).digest('hex')
const baseline=await Bun.file(new URL('./m68-independent-baseline.json',import.meta.url)).json()
let operator:WorkspaceConnection,runtime:WorkspaceConnection,db:HostedWorkspaceDatabase,app:Awaited<ReturnType<typeof createStagingServer>>,annual:any,evidence:any,current:any,report:any,reportBytes:Uint8Array,sources:any[]=[]
const construct=(c:WorkspaceConnection)=>new(HostedWorkspaceDatabase as unknown as new(c:WorkspaceConnection,r:string)=>HostedWorkspaceDatabase)(c,REF)
const request=(actor:keyof typeof ids|null,kind='annual-electricity-evidence',suffix='',payload?:unknown,c=company)=>app.fetch(new Request(`${ORIGIN}/workspace-api/workspace/${c}/${kind}${suffix}`,{method:payload===undefined?'GET':'POST',headers:{origin:ORIGIN,...(actor?{authorization:'Bearer '+actor}:{}),...(payload===undefined||payload instanceof FormData?{}:{'content-type':'application/json'})},body:payload===undefined?undefined:payload instanceof FormData?payload:JSON.stringify(payload)}))
const json=async(actor:keyof typeof ids,kind:string,suffix='',payload?:unknown,status=payload===undefined?200:201,c=company)=>{const r=await request(actor,kind,suffix,payload,c);expect(r.status,await r.clone().text()).toBe(status);return r.json() as Promise<any>}
const months=(j:string|null='0',rest:string|null=null)=>Array.from({length:12},(_,i)=>({month:`2023-${String(i+1).padStart(2,'0')}`,quantityKwh:i?rest:j}))
async function annualSave(rows=months(),label='Independent fictional facility'){const prior=annual?.versions.at(-1);annual=decodeAnnualElectricityWorksheet(await json('owner','annual-electricity-worksheet',prior?'/corrections':'',{companyLabel:'Synthetic QA <draft>',facilityLabel:label,year:2023,geography:'CAMX',unit:'kWh',months:rows,idempotencyKey:crypto.randomUUID(),...(prior?{expectedVersionId:prior.id,expectedResultSha256:prior.resultSha256,correctionReason:'Independent annual input correction'}:{})}),company);return annual.versions.at(-1)}
const link=(i=0,reason:string|null=null)=>({month:'2023-01',sourceId:sources[i].id,expectedSourceSha256:sources[i].sha256,sourcePage:1,manualConfirmation:true,quantityDifferenceReason:reason})
const input=(links:any[]=[],a=annual.versions.at(-1))=>({annualVersionId:a.id,expectedAnnualInputSha256:a.inputSha256,expectedAnnualResultSha256:a.resultSha256,links,idempotencyKey:crypto.randomUUID(),...(current?{expectedVersionId:current.id,expectedResultSha256:current.resultSha256,correctionReason:'Independent evidence correction'}:{})})
async function save(links:any[]=[],a=annual.versions.at(-1)){evidence=decodeAnnualElectricityEvidence(await json('owner','annual-electricity-evidence',current?'/corrections':'',input(links,a)),company,annual);current=evidence.versions.at(-1);return current}
const rp=(v=current)=>({sourceVersionId:v.id,expectedInputSha256:v.inputSha256,expectedResultSha256:v.resultSha256,expectedReviewId:v.review?.id??null,expectedReviewSha256:v.review?.decisionSha256??null,idempotencyKey:crypto.randomUUID()})
const review=(v=current)=>({versionId:v.id,expectedResultSha256:v.resultSha256,decision:'accept_bounded_internal_draft',note:null,acknowledgedLimitations:[...M68_LIMITATIONS],idempotencyKey:crypto.randomUUID()})
async function rejects(fn:()=>Promise<unknown>){let rejected=false;try{await fn()}catch{rejected=true}expect(rejected).toBe(true)}
async function preserved(){for(const t of baseline.rowHashes){const now=new Set((await operator.query<{value:any}>(`select to_jsonb(t) value from neuvetra.${t.table} t`)).rows.map(r=>hashManifestValue(r.value)));expect(t.hashes.every((h:string)=>now.has(h)),t.table).toBe(true)}}
const scoped=<T>(id:string|null,fn:(tx:WorkspaceSql)=>Promise<T>)=>runtime.transaction(async tx=>{await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[id??'']);return fn(tx)})
beforeAll(async()=>{
 operator=createPostgresConnection(url!,{tls:false});const manifest=await readMigrationManifest();expect(manifest).toHaveLength(14);expect(manifest[13]!.sha256).toBe('81686f3c62f8130a60dbbc096ae758eb6d56ecd80df3d533621a1990ae33d425')
 await migratePrivateStaging(operator,{expectedProjectRef:REF,syntheticTargetConfirmed:true})
 for(const id of Object.values(ids))await operator.query('insert into auth.users(id) values($1)',[id])
 await provisionStagingRoster(operator,{expectedProjectRef:REF,workspaceId:company,ownerUserId:ids.owner,members:[{userId:ids.admin,role:'admin'},{userId:ids.member,role:'member'}]})
 await provisionStagingRoster(operator,{expectedProjectRef:REF,workspaceId:otherCompany,ownerUserId:ids.other,members:[]})
 await operator.query("insert into neuvetra.company_members(company_id,user_id,role) values($1,$2,'admin')",[company,ids.uninvited])
 runtime=createPostgresConnection('postgres://neuvetra_runtime@127.0.0.1:55463/m68_qa',{tls:false,maxConnections:4});db=construct(runtime)
 app=await createStagingServer({profile:'neuvetra.private-synthetic-staging.v1',projectRef:REF,reuseExistingProject:false,origin:ORIGIN,supabaseUrl:`https://${REF}.supabase.co`,supabaseAnonKey:'synthetic-fixture',databaseUrl:url!,webRoot:'.',port:36668},{database:db,validateUser:async token=>token in ids?{id:ids[token as keyof typeof ids],email:null,phone:null,fullName:null}:null,verifyAssets:async()=>{},serveAsset:async()=>null,log:()=>{}})
},30000)
afterAll(async()=>{await app?.close();await operator?.close()})
test('migration14 retains all1894 independently frozen predecessor rows; sources are pinned originals',async()=>{
 expect((await db.checkReadiness()).schemaVersion).toBe(14);await preserved()
 for(const [name,pinned] of [['neuvetra-m55-synthetic-electricity-bill.pdf','0a97cd0976c03af0776214fc19bdc3d4f0c00e9c835f3e116574a6f375c8e135'],['neuvetra-m66-synthetic-electricity-bill-b.pdf','83e000a95f9e2f95473dc2cba18be0fc36810b24b9288f59b5aceb3a5ec0430f']]){const bytes=await Bun.file(new URL('../../output/pdf/'+name,import.meta.url)).bytes();expect(hash(bytes)).toBe(pinned!);const form=new FormData();form.set('file',new File([bytes],name!,{type:'application/pdf'}));form.set('idempotencyKey',crypto.randomUUID());sources.push(await json('owner','source-electricity-worksheet','/sources',form));const r=await request('member','source-electricity-worksheet','/sources/'+sources.at(-1).id+'/download');expect(r.status).toBe(200);expect(new Uint8Array(await r.arrayBuffer())).toEqual(bytes)}
})
test('explicit zero and unknown inputs retain separate evidence gaps and selected annual review is not inherited',async()=>{
 const a=await annualSave();annual=decodeAnnualElectricityWorksheet(await json('admin','annual-electricity-worksheet','/reviews',{...review(a),acknowledgedLimitations:[...M67_LIMITATIONS]}),company)
 await save();expect(current.coverage).toEqual({enteredMonths:1,missingInputMonths:months().slice(1).map(m=>m.month),linkedDocumentMonths:0,unambiguousDocumentMonths:0,missingDocumentMonths:months().map(m=>m.month),overlappingDocumentMonths:[],quantityDifferenceMonths:[]});expect(current.annual.months[0].quantityKwh).toBe('0.000');expect(current.annual.months[1].quantityKwh).toBeNull();expect(current.annual.review).toBeNull();expect(current.review).toBeNull()
 await save([link(0,'Zero differs from printed usage')]);expect(current.coverage.quantityDifferenceMonths).toEqual(['2023-01']);expect(current.coverage.unambiguousDocumentMonths).toBe(1);expect(current.annual.total.display).toBe('0.0000')
 report=decodeAnnualEvidenceReport(await json('owner','annual-electricity-evidence','/reports',rp()),evidence,annual);reportBytes=new Uint8Array(await(await request('member','annual-electricity-evidence',`/reports/${report.id}/download`)).arrayBuffer());expect(hash(reportBytes)).toBe(report.reportSha256)
})
test('source-only, explanation-only, annual-only successors pass actual decoder and preserve earlier report',async()=>{
 const before=current;await save([link(1,'Zero differs from printed usage')]);expect(current.annual).toEqual(before.annual);expect(current.links[0].source.id).toBe(sources[1].id)
 const replacement=current;await save([link(1,'Revised explanation; discrepancy remains')]);expect(current.annual).toEqual(replacement.annual);expect(current.coverage).toEqual(replacement.coverage)
 const explanation=current;await annualSave(months(),'Only changed the fictional facility label');await save([link(1,'Revised explanation; discrepancy remains')]);expect(current.annual.id).not.toBe(explanation.annual.id);expect(current.annual.total).toEqual(explanation.annual.total);expect(current.review).toBeNull()
 expect((await request('owner','annual-electricity-evidence','/corrections',input([link(1,'Revised explanation; discrepancy remains')]))).status).toBe(409)
 await save([link(0,'Unresolved A'),link(1,'Unresolved B')]);expect(current.coverage.linkedDocumentMonths).toBe(1);expect(current.coverage.unambiguousDocumentMonths).toBe(0);expect(current.coverage.overlappingDocumentMonths).toEqual(['2023-01']);expect(current.coverage.quantityDifferenceMonths).toEqual(['2023-01']);expect(current.annual.total.display).toBe('0.0000')
 expect((await request('owner','annual-electricity-evidence','/corrections',input([link(1,'Unresolved B'),link(0,'Unresolved A')]))).status).toBe(409)
 await save();expect(current.coverage.missingDocumentMonths).toHaveLength(12)
 expect(new Uint8Array(await(await request('member','annual-electricity-evidence',`/reports/${report.id}/download`)).arrayBuffer())).toEqual(reportBytes)
})
test('missing January cannot link; equal quantity requires no explanation; duplicate IDs and bytes and false periods refuse in HTTP and native SQL',async()=>{
 await annualSave(months(null,'1'));await save();const badMissing=input([link(0,'Missing January must not be inferred')]);expect((await request('owner','annual-electricity-evidence','/corrections',badMissing)).status).toBe(422)
 await annualSave(months('12345','0'));await save([link()]);expect(current.coverage.enteredMonths).toBe(12);expect(current.coverage.quantityDifferenceMonths).toEqual([]);expect(current.coverage.missingDocumentMonths).toHaveLength(11)
 const invalid=[[link(0,'Equal must be null')],[link(),link()],[link(),{...link(),sourceId:crypto.randomUUID()}],[{...link(),month:'2023-02'}],[{...link(),sourcePage:2}],[{...link(),manualConfirmation:false}],[{...link(),confirmedBy:ids.other}],[{...link(),quantityDifferenceReason:undefined}]]
 for(const links of invalid){const p=input(links);expect((await request('owner','annual-electricity-evidence','/corrections',p)).status).toBe(422);await rejects(()=>scoped(ids.owner,tx=>tx.query('select neuvetra.save_annual_electricity_evidence($1,$2::text::jsonb,true)',[company,JSON.stringify(p)])))}
})
test('native driver independently recomputed small, tie and maximal totals are reused through M68 API and decoder',async()=>{
 // integer millikWh times 1950402888 / 10^13 kg; display rounds quotient/remainder half-even at 4dp.
 for(const milli of [1n,62500000n,187500000n,1000000000n]){const q=`${milli/1000n}.${String(milli%1000n).padStart(3,'0')}`;await annualSave(months(q,'0'));await save();const numerator=milli*1950402888n,den=10000000000000n,whole=numerator/den,frac=String(numerator%den).padStart(13,'0').replace(/0+$/,'');const exact=String(whole)+(frac?'.'+frac:'');let d=numerator/1000000000n;const rem=numerator%1000000000n;if(rem>500000000n||(rem===500000000n&&d%2n===1n))d++;const display=`${d/10000n}.${String(d%10000n).padStart(4,'0')}`;expect(current.annual.total.unrounded).toBe(exact);expect(current.annual.total.display).toBe(display);expect(current.annual).toEqual({...annual.versions.at(-1),review:null})}
})
test('cross-tenant, uninvited, member, signed-out, self-review and competing saves reject at real boundaries',async()=>{
 for(const [actor,status] of [['member',200],['other',404],['outsider',403],['uninvited',403],[null,401]] as const){for(const suffix of ['', '/reports',`/reports/${report.id}`,`/reports/${report.id}/download`])expect((await request(actor,'annual-electricity-evidence',suffix)).status).toBe(status)}
 for(const id of [ids.member,ids.other,ids.outsider,ids.uninvited,null])await rejects(()=>scoped(id,tx=>tx.query('select neuvetra.save_annual_electricity_evidence($1,$2::text::jsonb,true)',[company,JSON.stringify(input())])))
 for(const id of [ids.other,ids.outsider,ids.uninvited,null])expect((await scoped(id,tx=>tx.query('select * from neuvetra.annual_electricity_evidence_versions where company_id=$1',[company]))).rows).toHaveLength(0)
 expect((await request('owner','annual-electricity-evidence','/reviews',review())).status).toBe(409)
 const left=input([link(0,'Concurrent A')]),right=input([link(1,'Concurrent B')]);const responses=await Promise.all([request('owner','annual-electricity-evidence','/corrections',left),request('admin','annual-electricity-evidence','/corrections',right)]);expect(responses.map(r=>r.status).sort()).toEqual([201,409]);evidence=decodeAnnualElectricityEvidence(await json('owner','annual-electricity-evidence'),company,annual);current=evidence.versions.at(-1)
 const reviewer=current.createdBy===ids.owner?'admin':'owner';const before=decodeAnnualEvidenceReport(await json('owner','annual-electricity-evidence','/reports',rp()),evidence,annual);const bytes=new Uint8Array(await(await request('member','annual-electricity-evidence',`/reports/${before.id}/download`)).arrayBuffer());evidence=decodeAnnualElectricityEvidence(await json(reviewer,'annual-electricity-evidence','/reviews',review()),company,annual);current=evidence.versions.at(-1);expect(current.review.reviewerId).toBe(ids[reviewer]);expect(decodeAnnualEvidenceReport(before,evidence,annual).reviewState).toBe('unreviewed');expect(new Uint8Array(await(await request('member','annual-electricity-evidence',`/reports/${before.id}/download`)).arrayBuffer())).toEqual(bytes)
